from z3 import *
import itertools

def solve_incremental():
    n = 14
    # Edge variables: e[i][j] for i<j
    edges = {}
    edge_list = []
    for i in range(n):
        for j in range(i+1, n):
            e = Bool(f'e_{i}_{j}')
            edges[(i,j)] = e
            edge_list.append(e)

    # Color variables: c[i] in {0,1,2}
    c = [Int(f'c_{i}') for i in range(n)]

    s = Solver()

    # Color domains
    for i in range(n):
        s.add(c[i] >= 0, c[i] <= 2)

    # 3-colorability: if edge exists, colors differ
    for (i,j), e in edges.items():
        s.add(Implies(e, c[i] != c[j]))

    # No triangles
    for trio in itertools.combinations(range(n), 3):
        i,j,k = trio
        s.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

    # No 4-cycles
    for quad in itertools.combinations(range(n), 4):
        a,b,cv,d = quad
        cycles4 = [
            (a,b,cv,d),
            (a,b,d,cv),
            (a,cv,b,d)
        ]
        for cycle in cycles4:
            v0,v1,v2,v3 = cycle
            e0 = edges[(min(v0,v1), max(v0,v1))]
            e1 = edges[(min(v1,v2), max(v1,v2))]
            e2 = edges[(min(v2,v3), max(v2,v3))]
            e3 = edges[(min(v3,v0), max(v3,v0))]
            s.add(Not(And(e0,e1,e2,e3)))

    # No 5-cycles
    for pent in itertools.combinations(range(n), 5):
        verts = list(pent)
        a = verts[0]
        rest = verts[1:]
        seen = set()
        for perm in itertools.permutations(rest):
            cycle = (a,) + perm
            rev = tuple(reversed(cycle))
            canon = min(cycle, rev)
            if canon in seen:
                continue
            seen.add(canon)
            clause = []
            valid = True
            for idx in range(5):
                v0 = cycle[idx]
                v1 = cycle[(idx+1)%5]
                if v0 == v1:
                    valid = False
                    break
                clause.append(edges[(min(v0,v1), max(v0,v1))])
            if valid:
                s.add(Not(And(clause)))

    # At least 18 edges
    s.add(PbGe([(e,1) for e in edge_list], 18))

    print("Initial constraints added. Starting iterative solving...")

    iteration = 0
    while True:
        res = s.check()
        print(f"Iteration {iteration}: {res}")
        if res != sat:
            return res, None

        m = s.model()
        # Extract graph
        G = set()
        for (i,j), e in edges.items():
            if m.evaluate(e):
                G.add((i,j))

        print(f"  Edges: {len(G)}")

        # Check for 6-cycles
        # Build adjacency list
        adj = {i: set() for i in range(n)}
        for (u,v) in G:
            adj[u].add(v)
            adj[v].add(u)

        # BFS to find shortest cycles
        found_6 = False
        for start in range(n):
            if found_6:
                break
            # BFS from start
            dist = {i: -1 for i in range(n)}
            parent = {i: None for i in range(n)}
            dist[start] = 0
            queue = [start]
            for u in queue:
                if found_6:
                    break
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif parent[u] != v and parent[v] != u:
                        # Found a cycle
                        # Reconstruct
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len == 6:
                            # Found 6-cycle
                            # Get paths from start to u and start to v
                            path_u = []
                            x = u
                            while x is not None:
                                path_u.append(x)
                                x = parent[x]
                            path_u.reverse()

                            path_v = []
                            x = v
                            while x is not None:
                                path_v.append(x)
                                x = parent[x]
                            path_v.reverse()

                            # Find common prefix
                            common = 0
                            while common < len(path_u) and common < len(path_v) and path_u[common] == path_v[common]:
                                common += 1
                            common -= 1

                            cycle = path_u[common:] + list(reversed(path_v[common+1:]))
                            if len(cycle) == 6:
                                # Add constraint to forbid this cycle
                                clause = []
                                for idx in range(6):
                                    v0 = cycle[idx]
                                    v1 = cycle[(idx+1)%6]
                                    clause.append(edges[(min(v0,v1), max(v0,v1))])
                                s.add(Not(And(clause)))
                                print(f"  Found 6-cycle: {cycle}, adding constraint")
                                found_6 = True
                                break

        if not found_6:
            # Also verify girth >= 7 by checking all cycle lengths
            min_cycle = float('inf')
            for start in range(n):
                dist = {i: -1 for i in range(n)}
                parent = {i: None for i in range(n)}
                dist[start] = 0
                queue = [start]
                for u in queue:
                    for v in adj[u]:
                        if dist[v] == -1:
                            dist[v] = dist[u] + 1
                            parent[v] = u
                            queue.append(v)
                        elif parent[u] != v and parent[v] != u:
                            cycle_len = dist[u] + dist[v] + 1
                            if cycle_len < min_cycle:
                                min_cycle = cycle_len

            print(f"  Minimum cycle length: {min_cycle}")
            if min_cycle >= 7:
                # Check 3-coloring
                coloring = [m.evaluate(c[i]).as_long() for i in range(n)]
                valid_color = True
                for (u,v) in G:
                    if coloring[u] == coloring[v]:
                        valid_color = False
                        break
                print(f"  Valid 3-coloring: {valid_color}")
                if valid_color:
                    return sat, sorted(G)

        iteration += 1
        if iteration > 1000:
            print("Too many iterations")
            return unknown, None

